import {speechChunks} from './speech-extract.js';
import {recognizeLocal,cancelLocalASR} from './local-asr.js';
import {productionPreferences} from './production-core.js';
export async function runLocalTranscription(api,options,progress,signal){const s=structuredClone(api.getState()),fingerprint=JSON.stringify(s.clips),p=productionPreferences(options),cues=[];let i=0;const stop=()=>signal?.aborted;const onAbort=()=>cancelLocalASR();signal?.addEventListener('abort',onAbort,{once:true});try{const duration=s.clips.reduce((n,c)=>n+(c.end-c.start)/c.speed,0);if(!duration)throw Error('Добавьте видео с речью на таймлайн.');for await(const c of speechChunks(s,api.getAssets(),{maxSeconds:12,stop})){if(stop())throw Error('Распознавание остановлено');i++;progress(`Распознаю речь: фрагмент ${i}/${Math.ceil(duration/12)}`);const result=c.silent?{cues:[]}:await recognizeLocal(c.wave,p.language,'small',v=>progress(v.status==='download'?`Загружаю Whisper: ${v.file||''} ${Math.round(v.progress||0)}%`:`Распознаю фрагмент ${i}/${Math.ceil(duration/12)}`));for(const q of result.cues)cues.push({...q,start:q.start+c.offset,end:q.end+c.offset,...(q.words?{words:q.words.map(w=>({...w,start:w.start+c.offset,end:w.end+c.offset}))}:{})});}if(stop())throw Error('Распознавание остановлено');if(!cues.length)throw Error('Разборчивая речь не обнаружена.');if(api.getState().projectId!==s.projectId||JSON.stringify(api.getState().clips)!==fingerprint)throw Error('Таймлайн изменился. Повторите распознавание.');await document.fonts.load(`700 40px "${p.font}"`);api.commit(()=>{const now=api.getState();now.cues=cues;now.captionsEnabled=true;now.captionStyle={...p,size:6.5,safe:18};now.captionSource='speech';now.transcript={text:cues.map(c=>c.text).join(' '),model:'Whisper Small',createdAt:new Date().toISOString()};now.clips.forEach(c=>c.title='')});return cues.length;}finally{signal?.removeEventListener('abort',onAbort)}}
